/**
 * Drives a tool's real Concrete CMS block in a DOM, with the real dist bundle
 * loaded the way a browser loads it, and checks what the page displays against
 * fixtures generated by the Python reference.
 *
 *   node build/browser_test.js                 # every tool
 *   node build/browser_test.js all-models      # one tool
 *
 * Per tool it reads:
 *   tools/<slug>/tool.json       method name, bundle filename
 *   tools/<slug>/block.html      the block that gets pasted into the site
 *   tools/<slug>/fixtures.json   expected output, from the Python reference
 *   tools/<slug>/form-map.js     how to drive this tool's controls
 *   dist/<output>                the built algorithm
 */
const fs = require('fs');
const path = require('path');
const { JSDOM } = require('jsdom');

const ROOT = path.join(__dirname, '..');
const TOOLS_DIR = path.join(ROOT, 'tools');

let pass = 0, fail = 0;
function check(name, cond, extra) {
  if (cond) { pass++; console.log('  PASS', name); }
  else { fail++; console.log('  FAIL', name, extra === undefined ? '' : String(extra).slice(0, 400)); }
}

function discover(slugs) {
  if (slugs.length) {
    for (const slug of slugs) {
      if (!fs.existsSync(path.join(TOOLS_DIR, slug, 'tool.json'))) {
        console.error('no such tool:', slug);
        process.exit(1);
      }
    }
    return slugs;
  }
  return fs.readdirSync(TOOLS_DIR)
    .filter(d => fs.existsSync(path.join(TOOLS_DIR, d, 'tool.json')))
    .sort();
}

function driver(dom) {
  const doc = dom.window.document;
  const Ev = dom.window.Event;
  return {
    doc,
    set(id, v) {
      const el = doc.getElementById('usg-' + id);
      if (!el) throw new Error('no control #usg-' + id);
      el.value = String(v);
      el.dispatchEvent(new Ev('change', { bubbles: true }));
    },
    radio(name, v) {
      const els = doc.querySelectorAll('input[name="usg-' + name + '"]');
      if (!els.length) throw new Error('no radio group usg-' + name);
      for (const el of els) {
        el.checked = el.value === v;
        if (el.checked) el.dispatchEvent(new Ev('change', { bubbles: true }));
      }
    },
    async run() {
      doc.getElementById('usg-run-btn').click();
      const out = doc.getElementById('usg-output');
      for (let i = 0; i < 100; i++) {
        await new Promise(r => setTimeout(r, 20));
        if (!out.querySelector('.usg-spinner')) break;
      }
      return {
        text: out.textContent,
        codes: Array.from(out.querySelectorAll('.usg-code')).map(c => c.textContent.trim()),
        adjustments: Array.from(out.querySelectorAll('.usg-table tbody tr'))
          .map(tr => Array.from(tr.querySelectorAll('td')).map(td => td.textContent.trim())),
        tables: Array.from(out.querySelectorAll('.usg-dfwrap')).map(w => ({
          title: w.previousElementSibling && w.previousElementSibling.classList.contains('usg-df-title')
            ? w.previousElementSibling.textContent.trim() : null,
          headers: Array.from(w.querySelectorAll('thead th')).map(t => t.textContent.trim()),
          rows: Array.from(w.querySelectorAll('tbody tr'))
            .map(tr => Array.from(tr.querySelectorAll('td')).map(td => td.textContent.trim()))
        })),
        sectionLabels: Array.from(out.querySelectorAll('.usg-section-label')).map(e => e.textContent.trim()),
        caption: (out.querySelector('.usg-caption') || {}).textContent,
        hasError: !!out.querySelector('.usg-error'),
        hasSuccess: !!out.querySelector('.usg-success'),
        hasWarning: !!out.querySelector('.usg-warning'),
        hasInfo: !!out.querySelector('.usg-info'),
        hasPdfBtn: !!doc.getElementById('usg-pdf-btn')
      };
    }
  };
}

async function testTool(slug) {
  const toolDir = path.join(TOOLS_DIR, slug);
  const cfg = JSON.parse(fs.readFileSync(path.join(toolDir, 'tool.json'), 'utf8'));
  const blockHtml = fs.readFileSync(path.join(toolDir, 'block.html'), 'utf8');
  const bundlePath = path.join(ROOT, 'dist', cfg.output);
  if (!fs.existsSync(bundlePath)) {
    console.error(`\n${slug}: dist/${cfg.output} missing - run python3 build/build.py ${slug}`);
    fail++;
    return;
  }
  const bundle = fs.readFileSync(bundlePath, 'utf8');
  const fixtures = JSON.parse(fs.readFileSync(path.join(toolDir, 'fixtures.json'), 'utf8'));
  const formMap = require(path.join(toolDir, 'form-map.js'));
  // The CDN <script> is swapped for the local bundle - the same file jsDelivr
  // will serve, so no network is needed. Everything else is byte-for-byte the
  // block that gets pasted into the site.
  function makePage(opts) {
    opts = opts || {};
    let html = blockHtml.replace(/<script src="https:\/\/cdn\.jsdelivr\.net[^"]*"><\/script>/,
      opts.omitAlgorithm ? '' : '<script>' + bundle + '</script>');
    html = html.replace(/<script src="https:\/\/cdnjs[^"]*"><\/script>/, '');
    return new JSDOM('<!doctype html><html><body>' + html + '</body></html>', {
      runScripts: 'dangerously',
      url: 'https://hollandsupplycompany.com' + (cfg.page || '/')
    });
  }

  console.log(`\n=== ${slug}: block contains no algorithm ===`);
  check('block carries no capacity data', blockHtml.length < 80000, blockHtml.length + ' bytes');
  check('loads its own bundle from jsDelivr',
    blockHtml.indexOf('cdn.jsdelivr.net') !== -1 && blockHtml.indexOf('dist/' + cfg.output) !== -1);
  check('calls its own namespace method',
    blockHtml.indexOf('USGSizing.' + cfg.method) !== -1 ||
    blockHtml.indexOf("USGSizing['" + cfg.method + "']") !== -1);

  console.log(`\n=== ${slug}: page shows exactly what Python computes ===`);
  for (const fx of fixtures) {
    const d = driver(makePage());
    formMap.fill(d, fx.input);
    const got = await d.run();
    const want = fx.expected;

    if (!want.ok) {
      check(fx.name + ' - same errors',
        got.hasError && want.errors.every(e => got.text.indexOf(e) !== -1), got.text.slice(0, 200));
      continue;
    }
    if (!want.selected) {
      const problems = [];
      if (!got.hasError || got.text.indexOf(want.message) === -1) problems.push('no-match message');
      // The 143 still lists every body size's capacities when nothing fits,
      // unless the algorithm stopped before producing them.
      const wantTableCount = want.tables
        ? want.tables.length
        : (want.sections ? want.sections.reduce((n, g) => n + g.tables.length, 0) : null);
      if (wantTableCount !== null) {
        const gotTables = got.tables.filter(t => t.title !== null);
        if (gotTables.length !== wantTableCount) {
          problems.push('table count ' + gotTables.length + ' vs ' + wantTableCount);
        }
      }
      if (want.stopped && got.tables.filter(t => t.title !== null).length) {
        problems.push('tables should not render when the algorithm stopped');
      }
      check(fx.name + ' - reports no match', problems.length === 0,
        problems.join('; ') + ' | ' + got.text.slice(0, 150));
      continue;
    }

    const problems = [];
    if (!got.hasSuccess) problems.push('no success box');
    for (const f of (want.selection || [])) {
      if (got.text.indexOf(f.label + ': ' + f.value) === -1) problems.push('missing ' + f.label + '=' + f.value);
    }
    if (want.capacity && got.text.indexOf('Calculated Capacity (CFH): ' + want.capacity) === -1) {
      problems.push('capacity ' + want.capacity);
    }
    if (JSON.stringify(got.codes) !== JSON.stringify(want.part_numbers || [])) {
      problems.push('part numbers ' + JSON.stringify(got.codes) + ' vs ' + JSON.stringify(want.part_numbers));
    }
    // Adjustments render in a plain .usg-table for tools without capacity
    // tables, and in a .usg-dfwrap alongside them for tools that have them.
    const wantAdj = (want.adjustments || []).map(a => [a.label, a.value]);
    const gotAdj = got.adjustments.length
      ? got.adjustments
      : (got.tables.filter(t => t.title === null).pop() || { rows: [] }).rows;
    if (JSON.stringify(gotAdj) !== JSON.stringify(wantAdj)) {
      problems.push('adjustments ' + JSON.stringify(gotAdj) + ' vs ' + JSON.stringify(wantAdj));
    }

    // Capacity tables grouped into labelled sections (the 046 shows both the
    // IRV and Monitor families when sizing for IRV). Labels and every cell are
    // compared against what Python computed.
    if (want.sections) {
      const wantLabels = want.sections.filter(g => g.label).map(g => g.label);
      if (JSON.stringify(got.sectionLabels) !== JSON.stringify(wantLabels)) {
        problems.push('section labels ' + JSON.stringify(got.sectionLabels) + ' vs ' + JSON.stringify(wantLabels));
      }
      const wantFlat = [];
      for (const g of want.sections) for (const t of g.tables) wantFlat.push(t);
      const gotTables = got.tables.filter(t => t.title !== null);
      if (gotTables.length !== wantFlat.length) {
        problems.push('table count ' + gotTables.length + ' vs ' + wantFlat.length);
      } else {
        for (let t = 0; t < wantFlat.length; t++) {
          if (gotTables[t].title !== wantFlat[t].title) {
            problems.push('table title ' + gotTables[t].title + ' vs ' + wantFlat[t].title);
          }
          if (JSON.stringify(gotTables[t].headers) !== JSON.stringify(wantFlat[t].headers)) {
            problems.push('headers differ in "' + wantFlat[t].title + '"');
          }
          if (JSON.stringify(gotTables[t].rows) !== JSON.stringify(wantFlat[t].rows)) {
            problems.push('rows differ in "' + wantFlat[t].title + '"');
          }
        }
      }
    }

    // Capacity tables, for tools that produce them (the 143's three body
    // sizes). Compared cell for cell against what Python computed.
    if (want.tables) {
      const gotTables = got.tables.filter(t => t.title !== null);
      if (gotTables.length !== want.tables.length) {
        problems.push('table count ' + gotTables.length + ' vs ' + want.tables.length);
      } else {
        for (let t = 0; t < want.tables.length; t++) {
          if (gotTables[t].title !== want.tables[t].title) {
            problems.push('table title ' + gotTables[t].title + ' vs ' + want.tables[t].title);
          }
          if (JSON.stringify(gotTables[t].headers) !== JSON.stringify(want.tables[t].headers)) {
            problems.push('table headers ' + JSON.stringify(gotTables[t].headers));
          }
          if (JSON.stringify(gotTables[t].rows) !== JSON.stringify(want.tables[t].rows)) {
            problems.push('rows differ in "' + want.tables[t].title + '"');
          }
        }
      }
    }
    for (const w of (want.warnings || [])) {
      if (got.text.indexOf(w) === -1) problems.push('warning ' + w);
    }
    if (want.pipe_note && got.text.indexOf(want.pipe_note) === -1) problems.push('pipe note');

    // Caption above the tables (the 121 shows one when a monitor is in play).
    if (want.tables_caption !== undefined) {
      const wantCaption = want.tables_caption || null;
      const gotCaption = got.caption ? got.caption.trim() : null;
      if (gotCaption !== wantCaption) {
        problems.push('caption ' + JSON.stringify(gotCaption) + ' vs ' + JSON.stringify(wantCaption));
      }
    }

    // Some tools gate the PDF button on a separate flag (the 121's apply121,
    // which can differ from having a match).
    const wantPdf = want.can_download === undefined ? true : !!want.can_download;
    if (got.hasPdfBtn !== wantPdf) {
      problems.push(wantPdf ? 'no PDF button' : 'PDF button should not render');
    }

    check(fx.name, problems.length === 0, problems.join('; '));
  }

  console.log(`\n=== ${slug}: algorithm fails to load ===`);
  {
    const d = driver(makePage({ omitAlgorithm: true }));
    formMap.fill(d, { inlet: 10, outlet: 2, flow: 500 });
    const got = await d.run();
    check('clear message, does not hang',
      got.hasError && got.text.indexOf('could not be loaded') !== -1, got.text.slice(0, 200));
  }

  console.log(`\n=== ${slug}: form behaviour ===`);
  {
    const dom = makePage();
    const d = driver(dom);
    formMap.formChecks(d, check);
    const tip = d.doc.querySelector('.usg-tipbox');
    const icons = d.doc.querySelectorAll('.usg-help');
    if (tip && icons.length) {
      icons[0].dispatchEvent(new dom.window.MouseEvent('click', { bubbles: true, cancelable: true }));
      check('tooltip opens on tap', tip.classList.contains('usg-show'));
      d.doc.body.dispatchEvent(new dom.window.MouseEvent('click', { bubbles: true, cancelable: true }));
      check('tooltip closes on outside tap', !tip.classList.contains('usg-show'));
    }
  }
}

(async () => {
  for (const slug of discover(process.argv.slice(2))) {
    await testTool(slug);
  }
  console.log(`\n${pass} passed, ${fail} failed\n`);
  process.exit(fail ? 1 : 0);
})();
